def g(en, kn, hi, te, ta):
    return dict(en=en, kn=kn, hi=hi, te=te, ta=ta)

def gv(text, mm, when=None):
    return {'text': text, 'm': mm, **({'when': when} if when else {})}

def with_tyaga(meaning, ty):
    return {l: meaning[l].rstrip() + ' ' + ty[l] for l in LANGS}

def old(si, vi):
    return dict(LIBO[NH]['sections'][si]['verses'][vi]['meaning'])

# tyaga phrases, per deity
def ty(en, kn, hi, te, ta):
    return svaha_add(en, kn, hi, te, ta)

