def graha_section(gr):
    key, title, titleEn, _, gvs, tyline, adhi, prati = gr
    vs = []
    for text, mm, w in gvs:
        vs.append(mv(text, mm, key, tyline, w))
    if key == 'shukra':
        for text, k, w in VENUS_ADHI:
            vs.append(mv(text, ADHI[k], 'indrani', 'स्वाहा । इन्द्राण्या इदं न मम ॥', w))
    elif key == 'rahu':
        for text, k, w in RAHU_ADHI:
            vs.append(mv(text, ADHI[k], 'sarpa', 'स्वाहा । सर्पेभ्य इदं न मम ॥', w))
    else:
        k, text, tl, tk = adhi
        vs.append(mv(text, ADHI[k], tk, tl))
    k, text, tl, tk = prati
    vs.append(mv(text, ADHI[k], tk, tl))
    d_en, d_kn = DRAVYA[key]
    l_en, l_kn = LORD[key]
    note = (f'Offer to {titleEn.split(" (")[0]}: {d_en}. With its graha mantra (first verse) offer the samidhs, then charu, then ghee, 108 times each for a full homa or 28 times each for the shorter padagraha-yajna (Matsya Purana 93.28-32; Homa-Havana); the samidhs a span long, dipped in honey, ghee and curd. '
            'Then offer to its adhidevata and pratyadhidevata with the next two verses, a tenth of that number (or as your purohita directs). Each oblation ends with svaha and the tyaga, इदं न मम. '
            f'Madhva anusandhana: the offering goes to {l_en}, the form of the Lord who rules this graha (Parashara Hora, in Homa-Havana), or to Lakshmi-Narasimha within Mukhyaprana in all the grahas.')
    note_kn = (f'{title_kn(key)}ಗೆ: {d_kn}. ಗ್ರಹಮಂತ್ರದಿಂದ (ಮೊದಲ ಮಂತ್ರ) ಸಮಿಧೆ, ನಂತರ ಚರು, ನಂತರ ತುಪ್ಪ — ಪೂರ್ಣ ಹೋಮಕ್ಕೆ ತಲಾ ೧೦೮, ಪಾದಗ್ರಹಯಜ್ಞಕ್ಕೆ ತಲಾ ೨೮ (ಮತ್ಸ್ಯಪುರಾಣ ೯೩.೨೮–೩೨; ಹೋಮ–ಹವನ); ಸಮಿಧೆಗಳು ಗೇಣುದ್ದ, ಜೇನು–ತುಪ್ಪ–ಮೊಸರಿನಲ್ಲಿ ಅದ್ದಿದವು. '
               'ನಂತರ ಮುಂದಿನ ಎರಡು ಮಂತ್ರಗಳಿಂದ ಅಧಿದೇವತೆ–ಪ್ರತ್ಯಧಿದೇವತೆಗಳಿಗೆ ಅದರ ದಶಾಂಶ (ಅಥವಾ ಪುರೋಹಿತರು ಹೇಳಿದಷ್ಟು). ಪ್ರತಿ ಆಹುತಿಯೂ ಸ್ವಾಹಾ ಮತ್ತು “ಇದಂ ನ ಮಮ” ತ್ಯಾಗದೊಡನೆ. '
               f'ಮಾಧ್ವ ಅನುಸಂಧಾನ: ಈ ಗ್ರಹನಿಯಾಮಕನಾದ ಭಗವದ್ರೂಪ {l_kn}ನಿಗೆ (ಪರಾಶರಹೋರಾ; ಹೋಮ–ಹವನ), ಅಥವಾ ಎಲ್ಲ ಗ್ರಹಗಳಲ್ಲೂ ಪ್ರಾಣಾಂತರ್ಗತ ಲಕ್ಷ್ಮೀನೃಸಿಂಹನಿಗೆ ಆಹುತಿ.')
    return Sec(title, titleEn, note, note_kn, vs)

def title_kn(k):
    return {'surya': 'ಸೂರ್ಯ', 'soma': 'ಚಂದ್ರ', 'angaraka': 'ಅಂಗಾರಕ', 'budha': 'ಬುಧ', 'brihaspati': 'ಬೃಹಸ್ಪತಿ', 'shukra': 'ಶುಕ್ರ', 'shani': 'ಶನೈಶ್ಚರ', 'rahu': 'ರಾಹು', 'ketu': 'ಕೇತು'}[k]

T['indrani'] = ty('Indrani', 'ಇಂದ್ರಾಣಿಗೆ', 'इन्द्राणी के लिए', 'ఇంద్రాణికి', 'இந்திராணிக்கு')

